// CHAT SESSIONS
app.get('/api/chat-sessions/:userId', async (req, res) => {
    const { userId } = req.params;
    const page = parseInt(req.query.page as string) || 1;
    const limit = parseInt(req.query.limit as string) || 10;
    const filterUserId = req.query.filterUserId as string || 'all';

    let matchStage: any = {};

    // Only apply filter if it's NOT 'all'
    if (userId !== 'all') {
        matchStage.userId = userId;
    } else if (filterUserId !== 'all') {
        matchStage.userId = filterUserId;
    }

    const sessions = await ChatLog.aggregate([
        { $match: matchStage },
        { $sort: { timestamp: -1 } },
        {
            $group: {
                _id: { userId: "$userId", sessionId: "$customerSessionId" },
                lastActive: { $max: "$timestamp" },
                preview: { $first: "$query" },
                messageCount: { $sum: 1 },
                userId: { $first: "$userId" },
                sessionId: { $first: "$customerSessionId" }
            }
        },
        { $sort: { lastActive: -1 } },
        { $skip: (page - 1) * limit },
        { $limit: limit }
    ]);

    // Count total distinct sessions for pagination
    // Note: This can be heavy on huge datasets, but okay for MVP
    const countResult = await ChatLog.aggregate([
        { $match: matchStage },
        { $group: { _id: { userId: "$userId", sessionId: "$customerSessionId" } } },
        { $count: "total" }
    ]);
    const total = countResult[0]?.total || 0;

    const mappedSessions = sessions.map(s => ({
        uniqueKey: `${s.userId}_${s.sessionId}`,
        ...s
    }));

    res.json({
        data: mappedSessions,
        pagination: { total, page, limit, totalPages: Math.ceil(total / limit) }
    });
});

