// Khi deploy lên Vercel, bạn cần set biến môi trường VITE_API_URL = https://your-koyeb-url.koyeb.app
const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:3001';
const DB_KEY = 'omnichat_db_v1';

const MASTER_USER: User = {
  id: 'admin',
  email: 'admin@bibichat.io',
  password: '123456',
  role: 'master',
  createdAt: Date.now(),
