app.get('/api/notifications/:userId', async (req, res) => {
    const { userId } = req.params;
    const now = Date.now();

    // Logic: 
    // 1. If user is Admin -> Fetch all (Admin created ones + System ones), no time limit
    // 2. If user is Regular -> Fetch their own specific ones OR 'all' (System ones), respecting schedule time

    let filter: any = {};

    if (userId === 'admin' || userId === 'master') {
        // Admin sees everything created for 'all' or specifically for 'admin' (testing)
        // Admin generally doesn't need to see notifications meant for other specific users, but can see system-wide broadcasts
        filter = {
            $or: [{ userId: 'all' }, { userId: 'admin' }]
        };
    } else {
        // Regular User
        filter = {
            $and: [
                { $or: [{ userId: 'all' }, { userId: userId }] },
                { 
                    $or: [
                        { scheduledAt: { $lte: now + 60000 } }, // +60s buffer for clock drift
                        { time: { $lte: now + 60000 } }, // Legacy field
                        { scheduledAt: { $exists: false } }
                    ] 
                }
            ]
        };
    }

    const notifs = await Notification.find(filter).sort({ scheduledAt: -1, time: -1 });

    const mapped = notifs.map(n => ({
        ...n.toObject(),
        isRead: n.readBy.includes(userId)
    }));

    res.json(mapped);
});

