        await fetch(`${API_URL}/api/plugins/${userId}`, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify(plugins)
        });
    } catch (e) {
        const db = getLocalDB();
        const idx = db.users.findIndex((u: any) => u.id === userId);
        if (idx !== -1) {
            db.users[idx].plugins = plugins;
            saveLocalDB(db);
        }
