  // --- ANALYTICS & LOGS (PAGINATED CHAT - HYBRID ONLINE/OFFLINE) ---

  // 1. Get List of Sessions (Paginated) with FULL Offline Support
  getChatSessionsPaginated: async (userId: string | 'all', page: number, limit: number, filterUserId: string = 'all'): Promise<{ data: any[], pagination: any }> => {
      try {
          const res = await fetch(`${API_URL}/api/chat-sessions/${userId}?page=${page}&limit=${limit}&filterUserId=${filterUserId}`);
          if(!res.ok) throw new Error("Fetch sessions failed");
          return await res.json();
      } catch (e) {
          // Offline Fallback Logic: Replicate Server grouping locally
          const db = getLocalDB();
          let allLogs = db.chatLogs || [];

          // Filter by Owner (similar to server)
          if (userId !== 'all') {
              allLogs = allLogs.filter((l: any) => l.userId === userId);
          } else {
              // Admin view offline
              if (filterUserId !== 'all') {
                  allLogs = allLogs.filter((l: any) => l.userId === filterUserId);
              }
          }

          // Grouping Logic
          const sessionsMap: Record<string, any> = {};
          allLogs.forEach((log: any) => {
              const sessId = log.customerSessionId || 'legacy_session';
              const key = `${log.userId}_${sessId}`; 
              if (!sessionsMap[key]) {
                  sessionsMap[key] = {
                      uniqueKey: key,
                      sessionId: sessId,
                      userId: log.userId,
                      lastActive: log.timestamp,
                      preview: log.query,
                      messageCount: 0
                  };
              }
              sessionsMap[key].messageCount++;
              if (log.timestamp > sessionsMap[key].lastActive) {
                  sessionsMap[key].lastActive = log.timestamp;
                  sessionsMap[key].preview = log.query;
              }
          });

          const sessions = Object.values(sessionsMap).sort((a: any, b: any) => b.lastActive - a.lastActive);
          const total = sessions.length;
          const startIndex = (page - 1) * limit;

          return { 
              data: sessions.slice(startIndex, startIndex + limit), 
              pagination: { 
                  total, 
                  page, 
                  limit, 
                  totalPages: Math.ceil(total / limit) 
              }
          };
      }
  },

  // 2. Get Messages for a specific session (Lazy Load) with FULL Offline Support
  getChatMessages: async (userId: string | 'all', sessionId: string): Promise<ChatLog[]> => {
      try {
          const res = await fetch(`${API_URL}/api/chat-messages/${userId}/${sessionId}`);
          if(!res.ok) throw new Error("Fetch messages failed");
          return await res.json();
      } catch (e) {
          // Offline Fallback
          const db = getLocalDB();
          const messages = (db.chatLogs || []).filter((l: any) => 
              (userId === 'all' || l.userId === userId) && 
              (l.customerSessionId === sessionId || (sessionId === 'legacy_session' && !l.customerSessionId))
          );
          return messages.sort((a: any, b: any) => a.timestamp - b.timestamp);
      }
  },

  getStats: async (userId: string | 'all', period: 'hour' | 'day' | 'week' | 'month') => {
    let logs: ChatLog[] = [];
    try {
        logs = await apiService.getChatLogs('all'); // Try fetch all to compute stats
    } catch (e) {
        const db = getLocalDB();
        logs = db.chatLogs;
    }
    if (userId !== 'all') logs = logs.filter(l => l.userId === userId);

    const statsMap: Record<string, { queries: number, solved: number }> = {};
    logs.forEach(log => {
      let key = '';
      const date = new Date(log.timestamp);
      if (period === 'hour') key = `${date.getHours()}h`;
      else if (period === 'day') key = date.toLocaleDateString('vi-VN');
      else if (period === 'week') key = `Tuần ${Math.ceil(date.getDate() / 7)}`;
      else key = `Tháng ${date.getMonth() + 1}`;
      if (!statsMap[key]) statsMap[key] = { queries: 0, solved: 0 };
      statsMap[key].queries++;
      if (log.isSolved) statsMap[key].solved++;
    });
    return Object.entries(statsMap).map(([label, data]) => ({ label, ...data }));
  },

  getChatLogs: async (userId: string | 'all'): Promise<ChatLog[]> => {
    try {
        const res = await fetch(`${API_URL}/api/chat-logs/${userId}`);
        if(!res.ok) throw new Error("Fetch logs failed");
        return await res.json();
    } catch (e) {
        const db = getLocalDB();
        let logs = db.chatLogs as ChatLog[];
        if (userId !== 'all') logs = logs.filter(l => l.userId === userId);
        return logs.sort((a, b) => b.timestamp - a.timestamp);
    }
  },

  // --- NOTIFICATIONS ---
  getNotifications: async (userId: string): Promise<Notification[]> => {
    try {
      const res = await fetch(`${API_URL}/api/notifications/${userId}`);
      if (!res.ok) throw new Error("Server error");
      return await res.json();
    } catch (e) {
      const db = getLocalDB();
      const now = Date.now();
      return (db.notifications || [])
        .filter((n: any) => {
          const isTargetUser = (n.userId === 'all' || n.userId === userId);
          if (!isTargetUser) return false;
          if (userId === 'admin') return true;
          return n.scheduledAt ? n.scheduledAt <= now : n.time <= now;
        })
        .map((n: any) => ({
            ...n,
            isRead: Array.isArray(n.readBy) ? n.readBy.includes(userId) : (n.isRead || false)
        }))
        .sort((a: any, b: any) => (b.scheduledAt || b.time) - (a.scheduledAt || a.time));
    }
  },

  markNotificationRead: async (id: string, userId: string): Promise<void> => {
    try {
      await fetch(`${API_URL}/api/notifications/${id}/read`, { 
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId })
      });
    } catch (e) {
      const db = getLocalDB();
      const n = db.notifications?.find((x: any) => x.id === id);
      if (n) {
        if (!n.readBy) n.readBy = [];
        if (!n.readBy.includes(userId)) n.readBy.push(userId);
        saveLocalDB(db);
      }
    }
  },

  markAllNotificationsRead: async (userId: string): Promise<void> => {
    try {
        await fetch(`${API_URL}/api/notifications/read-all`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ userId })
        });
    } catch (e) {
        const db = getLocalDB();
        const now = Date.now();
        db.notifications?.forEach((n: any) => {
            const isTargetUser = (n.userId === 'all' || n.userId === userId);
            const isVisible = userId === 'admin' ? true : (n.scheduledAt ? n.scheduledAt <= now : n.time <= now);
            if (isTargetUser && isVisible) {
                if (!n.readBy) n.readBy = [];
                if (!n.readBy.includes(userId)) n.readBy.push(userId);
            }
        });
        saveLocalDB(db);
    }
  },

  createSystemNotification: async (data: Partial<Notification>) => {
    try {
      await fetch(`${API_URL}/api/notifications/create`, {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify(data)
      });
    } catch (e) {
      const db = getLocalDB();
      if (!db.notifications) db.notifications = [];
      const now = Date.now();
      db.notifications.push({
        id: Math.random().toString(36).substr(2, 9),
        userId: data.userId || 'all',
        title: data.title || '',
        desc: data.desc || '',
        time: data.scheduledAt || now, 
        scheduledAt: data.scheduledAt || now,
        readBy: [],
        icon: data.icon || 'fa-bell',
        color: data.color || 'text-blue-500',
        bg: data.bg || 'bg-blue-100'
      });
      saveLocalDB(db);
    }
  },

  suggestIcon: async (text: string): Promise<string> => {
    const apiKey = getApiKey();
    if (!apiKey) return 'fa-bullhorn';

    try {
      const ai = new GoogleGenAI({ apiKey });
      const prompt = `Based on the following notification text, suggest the single most appropriate FontAwesome 6 icon class name. ONLY return the class name string. Text: "${text}"`;
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
      const iconClass = response.text?.trim() || 'fa-bullhorn';
      return iconClass.replace(/['".]/g, '');
    } catch (error) { return 'fa-bullhorn'; }
  },

  chat: async (userId: string, message: string, botName: string, sessionId: string): Promise<string> => {
    try {
      const res = await fetch(`${API_URL}/api/chat`, {
         method: 'POST',
         headers: { 'Content-Type': 'application/json' },
         body: JSON.stringify({ userId, message, botName, sessionId })
      });
      if(res.ok) {
         const data = await res.json();
         return data.text;
      }
    } catch (e) {}

    try {
      const apiKey = getApiKey();
      if (!apiKey) {
          // Trả về hướng dẫn chi tiết cho người dùng
          return "⚠️ Lỗi cấu hình: Thiếu API Key.\n\nHệ thống không tìm thấy API Key để chạy AI.\n\n👉 Cách khắc phục:\n1. Vào Vercel > Settings > Environment Variables.\n2. Thêm key: API_KEY = [Key Gemini của bạn].\n3. Redeploy lại ứng dụng.\n\nHoặc mở Console (F12) và nhập: localStorage.setItem('API_KEY', 'your-key') để test nhanh.";
      }

      const db = getLocalDB();
      const docs = db.documents.filter((d: any) => d.userId === userId);
      const context = docs.map((d: any) => `[Tài liệu: ${d.name}]\n${d.content}`).join('\n\n');
      const systemInstruction = `Bạn là trợ lý AI tên "${botName || 'BibiBot'}". Hãy sử dụng kiến thức sau để hỗ trợ khách hàng: ${context}`;

      const ai = new GoogleGenAI({ apiKey });
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: message, config: { systemInstruction } });

      if (!db.chatLogs) db.chatLogs = [];
      db.chatLogs.push({ id: Math.random().toString(36).substr(2, 9), userId, customerSessionId: sessionId || 'client-fallback', query: message, answer: response.text || '', timestamp: Date.now(), isSolved: true });
      saveLocalDB(db);

      return response.text || "Tôi không thể trả lời lúc này.";
    } catch (clientError) { 
        console.error(clientError);
        return "Lỗi kết nối AI. Vui lòng kiểm tra lại API Key hoặc thử lại sau."; 
    }
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { apiService } from '../services/apiService';
import { User, ConversationUser, DirectMessage } from '../types';

interface Props {
  user: User;
}

const CommunityChat: React.FC<Props> = ({ user }) => {
  const [conversations, setConversations] = useState<ConversationUser[]>([]);
  const [activeChatUser, setActiveChatUser] = useState<ConversationUser | null>(null);
  const [messages, setMessages] = useState<DirectMessage[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [searchEmail, setSearchEmail] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [searchError, setSearchError] = useState('');

  const scrollRef = useRef<HTMLDivElement>(null);
  const [isLoadingMessages, setIsLoadingMessages] = useState(false);

  // Load conversations list
  useEffect(() => {
    loadConversations();
    // Short polling for conversation updates (new messages from others)
    const interval = setInterval(loadConversations, 5000); 
    return () => clearInterval(interval);
  }, [user.id]);

  // Load messages when active chat changes
  useEffect(() => {
    if (activeChatUser) {
      loadMessages(activeChatUser.id);
      // Short polling for messages in active chat
      const interval = setInterval(() => loadMessages(activeChatUser.id), 3000);
      return () => clearInterval(interval);
    }
  }, [activeChatUser]);

  // Scroll to bottom on new message
  useEffect(() => {
    if (scrollRef.current) {
        scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const loadConversations = async () => {
    try {
      const data = await apiService.getConversations(user.id);

      // Automatic "Admin" contact for normal users if not exists
      if (user.role === 'user') {
          const adminExists = data.find(c => c.role === 'master' || c.id === 'admin');
          if (!adminExists) {
              // Add pseudo admin contact
              data.unshift({
                  id: 'admin',
                  email: 'admin@bibichat.io',
                  role: 'master',
                  lastMessage: 'Chào mừng bạn đến với cộng đồng!',
                  lastMessageTime: Date.now()
              });
          }
      }

      setConversations(data);
    } catch (e) {
      console.error("Failed to load conversations", e);
    }
  };

  const loadMessages = async (otherUserId: string) => {
      // Don't show loading on poll updates to prevent flicker, only on initial select
      if (!messages.length) setIsLoadingMessages(true); 
      try {
          const msgs = await apiService.getDirectMessages(user.id, otherUserId);
          setMessages(msgs);
      } catch (e) {
          console.error(e);
      } finally {
          setIsLoadingMessages(false);
      }
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
      e?.preventDefault();
      if (!newMessage.trim() || !activeChatUser) return;

      const content = newMessage;
      setNewMessage(''); // Optimistic clear

      // Optimistic update
      const tempMsg: DirectMessage = {
          id: Date.now().toString(),
          senderId: user.id,
          receiverId: activeChatUser.id,
          content: content,
          timestamp: Date.now(),
          isRead: false
      };
      setMessages(prev => [...prev, tempMsg]);

      try {
          await apiService.sendDirectMessage(user.id, activeChatUser.id, content);
          loadConversations(); // Update list preview
      } catch (e) {
          console.error("Failed to send", e);
          alert("Gửi tin nhắn thất bại");
      }
  };

  const handleAddUser = async () => {
      if (!searchEmail) return;
      setIsSearching(true);
      setSearchError('');

      try {
          // Check if searching for self
          if (searchEmail.toLowerCase() === user.email.toLowerCase()) {
              setSearchError("Bạn không thể chat với chính mình.");
              setIsSearching(false);
              return;
          }

          const result = await apiService.findUserByEmail(searchEmail);

          if (result.success && result.user) {
              const newUser = result.user;
              // Check if already in list
              const existing = conversations.find(c => c.id === newUser.id);
              if (existing) {
                  setActiveChatUser(existing);
              } else {
                  // Create temp conversation item
                  const newConv: ConversationUser = {
                      id: newUser.id,
                      email: newUser.email,
                      role: newUser.role,
                      lastMessage: '',
                      lastMessageTime: Date.now()
                  };
                  setConversations(prev => [newConv, ...prev]);
                  setActiveChatUser(newConv);
              }
              setSearchEmail('');
          } else {
              setSearchError(result.message || 'Không tìm thấy người dùng.');
          }
      } catch (e) {
          setSearchError('Lỗi kết nối.');
      } finally {
          setIsSearching(false);
      }
  };

  return (
    <div className="h-[calc(100vh-8rem)] min-h-[600px] flex gap-6 animate-in fade-in duration-500 pb-2">
       {/* Sidebar List */}
       <div className="w-full md:w-80 bg-white dark:bg-slate-800 rounded-[2.5rem] border border-slate-100 dark:border-slate-700 shadow-xl overflow-hidden flex flex-col shrink-0">
           <div className="p-6 border-b border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-800/50">
               <h3 className="font-black text-xl text-slate-800 dark:text-white mb-4 flex items-center gap-2">
                   <i className="fa-solid fa-comments text-indigo-500"></i> Trò chuyện
               </h3>

               {/* Search User Input */}
               <div className="relative">
                   <input 
                      type="email" 
                      placeholder="Nhập email kết nối..."
                      value={searchEmail}
                      onChange={(e) => setSearchEmail(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleAddUser()}
                      className="w-full pl-4 pr-10 py-3 bg-white dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-600 rounded-xl text-sm font-bold outline-none focus:border-indigo-500 transition-all"
                   />
                   <button 
                      onClick={handleAddUser}
                      disabled={isSearching}
                      className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 flex items-center justify-center text-indigo-500 hover:bg-indigo-50 rounded-lg transition-colors"
                   >
                       {isSearching ? <i className="fa-solid fa-circle-notch animate-spin"></i> : <i className="fa-solid fa-plus"></i>}
                   </button>
               </div>
               {searchError && <p className="text-xs text-rose-500 font-bold mt-2 ml-1">{searchError}</p>}
           </div>

           <div className="flex-1 overflow-y-auto p-3 space-y-2">
               {conversations.map(conv => (
                   <div 
                      key={conv.id}
                      onClick={() => setActiveChatUser(conv)}
                      className={`p-3 rounded-2xl cursor-pointer flex gap-3 items-center transition-all ${activeChatUser?.id === conv.id ? 'bg-indigo-50 dark:bg-slate-700 border-indigo-200 dark:border-slate-600 shadow-sm' : 'hover:bg-slate-50 dark:hover:bg-slate-700/50 border-transparent'} border-2`}
                   >
                       <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white shrink-0 ${conv.role === 'master' ? 'bg-gradient-to-br from-indigo-500 to-purple-600' : 'bg-gradient-to-br from-pink-400 to-orange-400'}`}>
                           {conv.role === 'master' ? <i className="fa-solid fa-user-shield"></i> : conv.email.charAt(0).toUpperCase()}
                       </div>
                       <div className="flex-1 min-w-0">
                           <div className="flex justify-between items-baseline mb-0.5">
                               <h4 className="font-bold text-sm text-slate-700 dark:text-slate-200 truncate">{conv.role === 'master' ? 'Admin Hỗ Trợ' : conv.email}</h4>
                               <span className="text-[10px] text-slate-400 font-bold">{conv.lastMessageTime > 0 ? new Date(conv.lastMessageTime).toLocaleTimeString('vi-VN', {hour: '2-digit', minute:'2-digit'}) : ''}</span>
                           </div>
                           <p className="text-xs text-slate-500 dark:text-slate-400 truncate font-medium">{conv.lastMessage || 'Chưa có tin nhắn'}</p>
                       </div>
                   </div>
               ))}
               {conversations.length === 0 && (
                   <div className="text-center py-10 opacity-50">
                       <i className="fa-solid fa-user-group text-3xl mb-2"></i>
                       <p className="text-xs font-bold">Chưa có cuộc trò chuyện nào</p>
                   </div>
               )}
           </div>
       </div>

       {/* Chat Area */}
       <div className="flex-1 bg-white dark:bg-slate-800 rounded-[2.5rem] border border-slate-100 dark:border-slate-700 shadow-xl overflow-hidden flex flex-col relative">
           {activeChatUser ? (
               <>
                   {/* Chat Header */}
                   <div className="p-4 border-b border-slate-100 dark:border-slate-700 flex items-center gap-4 bg-white/80 dark:bg-slate-800/80 backdrop-blur-md z-10">
                       <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white shadow-sm ${activeChatUser.role === 'master' ? 'bg-gradient-to-br from-indigo-500 to-purple-600' : 'bg-gradient-to-br from-pink-400 to-orange-400'}`}>
                           {activeChatUser.role === 'master' ? <i className="fa-solid fa-user-shield"></i> : activeChatUser.email.charAt(0).toUpperCase()}
                       </div>
                       <div>
                           <h3 className="font-bold text-slate-800 dark:text-white text-base">{activeChatUser.role === 'master' ? 'Admin Hỗ Trợ' : activeChatUser.email}</h3>
                           <p className="text-xs text-emerald-500 font-bold flex items-center gap-1"><span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span> Online</p>
                       </div>
                   </div>

                   {/* Messages List */}
                   <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50 dark:bg-slate-900" ref={scrollRef}>
                       {messages.map(msg => {
                           const isMe = msg.senderId === user.id;
                           return (
                               <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                                   <div className={`max-w-[70%] px-5 py-3 rounded-2xl text-sm font-medium leading-relaxed shadow-sm ${isMe ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 border border-slate-200 dark:border-slate-700 rounded-tl-none'}`}>
                                       {msg.content}
                                       <div className={`text-[9px] font-bold mt-1 text-right ${isMe ? 'text-indigo-200' : 'text-slate-400'}`}>
                                           {new Date(msg.timestamp).toLocaleTimeString('vi-VN', {hour:'2-digit', minute:'2-digit'})}
                                       </div>
                                   </div>
                               </div>
                           );
                       })}
                       {messages.length === 0 && (
                           <div className="flex flex-col items-center justify-center h-full opacity-40">
                               <i className="fa-regular fa-paper-plane text-4xl mb-2"></i>
                               <p className="text-sm font-bold">Bắt đầu trò chuyện ngay đi nào!</p>
                           </div>
                       )}
                   </div>

                   {/* Input Area */}
                   <form onSubmit={handleSendMessage} className="p-4 bg-white dark:bg-slate-800 border-t border-slate-100 dark:border-slate-700">
                       <div className="flex gap-3">
                           <input 
                              type="text" 
                              value={newMessage}
                              onChange={(e) => setNewMessage(e.target.value)}
                              placeholder="Nhập tin nhắn..." 
                              className="flex-1 px-5 py-3 bg-slate-100 dark:bg-slate-900 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-100 dark:focus:ring-indigo-900 text-sm font-medium text-slate-800 dark:text-white transition-all"
                           />
                           <button 
                              type="submit" 
                              disabled={!newMessage.trim()}
                              className="w-12 h-12 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-200 dark:shadow-none transition-all active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
                           >
                               <i className="fa-solid fa-paper-plane"></i>
                           </button>
                       </div>
                   </form>
               </>
           ) : (
               <div className="flex flex-col items-center justify-center h-full text-slate-400 dark:text-slate-600">
                   <div className="w-20 h-20 bg-slate-100 dark:bg-slate-700 rounded-full flex items-center justify-center mb-4">
                       <i className="fa-solid fa-comments text-3xl"></i>
                   </div>
                   <h3 className="font-bold text-lg text-slate-600 dark:text-slate-400">Chọn người để chat</h3>
                   <p className="text-sm font-medium">Hoặc thêm mới bằng email bên trái nha.</p>
               </div>
           )}
       </div>
    </div>
  );
};

export default CommunityChat;

