  useEffect(() => {
    if (isLoggedIn && currentUser && !isEmbedMode) {
      loadNotifications();
      loadUnreadMessages(); // Initial load

      const interval = setInterval(() => {
          loadNotifications();
          loadUnreadMessages();
      }, 5000);

      return () => {
        clearInterval(interval);
