    res.json({ success: true });
});

app.post('/api/notifications/read-all', async (req, res) => {
    const { userId } = req.body;
    const filter = { $or: [{ userId: 'all' }, { userId: userId }] };

    await Notification.updateMany(
        filter,
        { $addToSet: { readBy: userId } }
    );
    res.json({ success: true });
});

